window.TEST_PARTS=window.TEST_PARTS||{};window.TEST_PARTS["test4"]=(window.TEST_PARTS["test4"]||[]).concat([{"n":1,"page":1,"q":"Թույլատրվու՞մ է արդյոք մուտք գործել այս նշանով գոտի՝ աջ շրջադարձ կատարելիս։","options":["Թույլատրվում է","Արգելվում է","Թույլատրվում է, եթե այդ գոտին մնացած երթեւեկելի մասից բաժանված չէ գծանշման հոծ գծով"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":2,"page":1,"q":"Այս ճանապարհային նշանը ցույց է տալիս","options":["Ճանապարհի հատված, որտեղ առկա է մայթ կամ հետիոտնային արահետ։","Ճանապարհի հատված, որտեղ առկա է հետիոտնային անցում։","Ճանապարհի հատված, որտեղ չկա մայթ կամ հետիոտնային արահետ։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":3,"page":2,"q":"Նշաններից ո՞րն է արգելում երթեւեկությունը նշանի վրա պատկերվածից ավելի փոքր միջտարածությամբ։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":4,"page":2,"q":"Ճանապարհի վտանգավոր հատվածի տեղամասից ի՞նչ հեռավորության վրա են տեղադրվում այս նշանները բնակավայրերում։","options":["15 - 25 մ","25 - 50 մ","50 - 100 մ","100 - 150 մ","150 - 300 մ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":5,"page":3,"q":"Այս ճանապարհային նշանը","options":["Արգելում է բոլոր մեխանիկական տրանսպորտային միջոցների երթեւեկությունը՝ բացառությամբ առանց կողային կցորդի երկանիվ մոտոցիկլների։","Արգելում է բոլոր տրանսպորտային միջոցների երթեւեկությունը՝ բացառությամբ անվավոր տրակտորների։","Արգելում է տրակտորների եւ ինքնագնաց մեքենաների երթեւեկությունը։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":6,"page":3,"q":"Նշաններից ո՞րն է պարտադրում զիջել ճանապարհը հանդիպակաց ուղղությամբ ճանապարհի նեղ հատված մուտք գործող կամ դրան մոտեցող տրանսպորտային միջոցներին։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":7,"page":4,"q":"Նշաններից ո՞րն է նախազգուշացնում հավասարազոր ճանապարհների խաչմերուկին մոտենալու մասին։","options":["1","2","3","4","5"],"ans":5,"images_inline":["data:image/jpeg;base64,"]},{"n":8,"page":4,"q":"Նշաններից ո՞րն է տեղադրվում երթեւեկելի մասերի հատումից անմիջապես առաջ։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":9,"page":5,"q":"Այս նշանները թույլատրում են երթեւեկությունը","options":["Միայն դեպի ձախ։","Միայն ուղիղ։","Միայն դեպի աջ։","Ուղիղ, դեպի աջ եւ հակառակ ուղղությամբ։"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":10,"page":5,"q":"Նշաններից ո՞րն է վարորդին առավելություն տալիս հանդիպակաց տրանսպորտային միջոցների նկատմամբ։","options":["1","2","3","4","5"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":11,"page":6,"q":"Ի՞նչ է ցույց տալիս նշանի տակ տեղադրված ցուցանակը։","options":["Նշանից մինչեւ առաջին շրջադարձի սկիզբը եղած հեռավորությունը","Առաջին շրջադարձից մինչեւ երկրորդ շրջադարձի սկիզբը եղած հեռավորությունը","Վտանգավոր շրջադարձերով ճանապարհի հատվածի երկարությունը"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":12,"page":6,"q":"Ի՞նչ է ցույց տալիս հետեւյալ նշանների համադրությունը։","options":["Մոտոցիկլների երթեւեկությունը դեպի աջ արգելվում է։","Մոտոցիկլների երթեւեկությունը դեպի աջ թույլատրվում է։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":13,"page":7,"q":"Նշաններից ո՞րն է արգելում կայանումն ամսվա զույգ օրերին։","options":["1","2","3","4","5"],"ans":5,"images_inline":["data:image/jpeg;base64,"]},{"n":14,"page":7,"q":"Այս ճանապարհային նշանը","options":["Թույլատրում է երթեւեկել միայն նշված կամ ավելի բարձր արագությամբ։","Արգելում է երթեւեկել նշանի վրա նշվածից ավելի բարձր արագությամբ։","Ցույց է տալիս այն արագությունը, որով առաջարկվում է երթեւեկել ճանապարհի տվյալ հատվածում։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":15,"page":8,"q":"Հետեւյալ նշաններից ո՞րն է պարտադրում զիջել ճանապարհը հանդիպակաց երթեւեկող տրանսպորտային միջոցներին։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":16,"page":8,"q":"Այս նշանը կոչվում է","options":["Արգելքի շրջանցման նախնական ցուցիչ։","Այլ երթեւեկելի մաս վերադասավորվելու նախնական ցուցիչ։","Հանդիպակաց երթեւեկության գոտի դուրս գալու նախնական ցուցիչ։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":17,"page":9,"q":"Նշաններից ո՞րն է պարտադրում զիջել ճանապարհը հատվող ճանապարհով ընթացող տրանսպորտային միջոցներին։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":18,"page":9,"q":"Հետեւյալ նշաններից ո՞րն է թույլատրում երթեւեկել միայն նշված կամ ավելի բարձր արագությամբ (կմ/ժ)։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":19,"page":10,"q":"Նշաններից ո՞րն է ցույց տալիս միակողմ երթեւեկության ճանապարհի հատվածը։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":20,"page":10,"q":"Ի՞նչ է ցույց տալիս հիմնական նշանի հետ կիրառվող ցուցանակը","options":["Ճանապարհի նեղ հատվածի երկարությունը։","Նշանից մինչեւ սահմանափակման տեղն ընկած հեռավորությունը։","Մինչեւ ճանապարհի նեղ հատվածի շրջանցման տեղն ընկած հեռավորությունը։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":21,"page":11,"q":"Այս ճանապարհային նշանը նախազգուշացնում է, որ առջեւում","options":["Կամուրջ կամ լաստանավային անցում չունեցող ջրային արգելքով ճանապարհահատված է։","Ջրային արգելքով ճանապարհահատված է, որի վրա առկա է բացվող կամուրջ։","Տեղամաս է, որտեղ ճանապարհը դուրս է գալիս ափ կամ առափ։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":22,"page":11,"q":"Նշվածներից ո՞րն է ցույց տալիս տրանսպորտային միջոցների կանգառն ու կայանումն արգելող ճանապարհային նշանների ազդման գոտին։","options":["1","2","3","4","5"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":23,"page":12,"q":"Նշաններից ո՞րն է ցույց տալիս նախազգուշացնող նշանների ազդեցության` ճանապարհի վտանգավոր հատվածի երկարությունը։","options":["1","2","3","4","5"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":24,"page":12,"q":"Այս ճանապարհային նշանը ցույց է տալիս","options":["Միակողմ երթեւեկությամբ ճանապարհ, որով թույլատրվում է միայն բեռնատար ավտոմոբիլների երթեւեկությունը։","Միայն բեռնատար ավտոմոբիլների երթեւեկության համար նախատեսված գոտին։","Բեռնատար ավտոմոբիլների համար առաջարկվող երթեւեկության ուղղությունը։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":25,"page":13,"q":"Նշաններից ո՞րն է ցույց տալիս «Հյուրանոց» կամ «Մոթել»։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":26,"page":13,"q":"Այսպիսի ճանաչման նշանով կահավորվում են այն ավտոմոբիլները, որոնք","options":["Փոխադրում են վտանգավոր բեռներ։","Ղեկավարվում են հաշմանդամների կողմից։","Ղեկավարվում են խուլ կամ խուլ ու համր վարորդների կողմից։","Ղեկավարվում են մինչեւ 3 տարի վարորդական փորձ ունեցող վարորդների կողմից։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":27,"page":14,"q":"Նշաններից ո՞րն է ցույց տալիս 50 կմ/ժ առավելագույն արագության սահմանափակման գոտու վերջը։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":28,"page":14,"q":"Ինչի՞ մասին են զգուշացնում այս նշանը եւ ցուցանակը։","options":["Նորոգման աշխատանքների կատարման պատճառով ճանապարհի կողնակին կանգառ կատարելն արգելվում է","Նորոգման աշխատանքների կատարման պատճառով ճանապարհի կողնակ մուտք գործելը վտանգավոր է","Նորոգման աշխատանքների կատարման պատճառով ճանապարհի կողնակին կայանելն արգելում է"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":29,"page":15,"q":"Այսպիսի ճանաչման նշանով են կահավորվում այն տրանսպորտային միջոցները, որոնք","options":["Ղեկավարվում են հաշմանդամների կողմից։","Փոխադրում են ծանրաքաշ եւ մեծ եզրաչափերով բեռներ։","Փոխադրում են վտանգավոր բեռներ։","Ղեկավարվում են խուլ կամ խուլ ու համր վարորդների կողմից։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":30,"page":15,"q":"Նշաններից ո՞րն է վերացնում նախկին բոլոր սահմանափակումները։","options":["1","2","3","4","5"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":31,"page":16,"q":"Ո՞ր դեպքում է վարորդը ճիշտ կատարել այս նշանի պահանջները։","options":["Զիջել է ճանապարհը հատվող ճանապարհով ընթացող մեխանիկական տրանսպորտային միջոցներին","Զիջել է ճանապարհը հատվող ճանապարհով ընթացող տրանսպորտային միջոցներին"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":32,"page":16,"q":"Տեղադրվածներից ո՞րն է կիրառվում որպես ավտոգնացքի ճանաչման նշան։","options":["Ձախ նշանը","Աջ նշանը","Երկու նշաններն էլ"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":33,"page":17,"q":"Ո՞ր նշանն է պարտադրում զիջել ճանապարհը հատվող ճանապարհով երթեւեկող տրանսպորտային միջոցներին։","options":["1","2","3","4","5"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":34,"page":17,"q":"Հետեւյալ նշաններից (ցուցանակներից) ո՞րն է ցույց տալիս տրանսպորտային միջոցի կանգնեցման ձեւը կայանման տեղերում։","options":["1","2","3","4","5"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":35,"page":18,"q":"Թույլատրվու՞մ է արդյոք ուղեւորներ նստեցնելու համար կանգ առնել այս նշանով նշված գոտու վրա։","options":["Թույլատրվում է, եթե այդ գոտին գտնվում է երթեւեկելի մասի աջ եզրի մոտ եւ մնացած երթեւեկելի մասից բաժանված չէ գծանշման հոծ գծով","Արգելվում է","Թույլատրվում է"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":36,"page":18,"q":"Այս ճանապարհային նշանի առկայության դեպքում","options":["Արգելվում է բոլոր տեսակի տրանսպորտային միջոցներով վազանցի կատարումը՝ բացառությամբ դանդաղընթաց տրանսպորտային միջոցների, լծասայլերի, առանց կողային կցորդի երկանիվ մոտոցիկլների, մոպեդների եւ հեծանիվների։","Թույլատրվում է 3.5 տ ոչ ավելի թույլատրելի առավելագույն զանգված ունեցող բեռնատար ավտոմոբիլներով վազանցի կատարումը։","Թույլատրվում է վազանցի կատարումը, եթե վազանցող տրանսպորտային միջոցի արագությունը չի գերազանցում 30 կմ/ժ։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":37,"page":19,"q":"Նշաններից ո՞րն է ցույց տալիս «Հատում հեծանվային արահետի հետ»։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":38,"page":19,"q":"Նշաններից ո՞րն է ցույց տալիս վազանցի արգելման գոտու վերջը։","options":["1","2","3","4","5"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":39,"page":20,"q":"Նշաններից ո՞րն է ցույց տալիս երթեւեկության ուղղությունները T-աձեւ խաչմերուկում։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":40,"page":20,"q":"Այս ճանապարհային նշանը ցույց է տալիս","options":["Միջանցիկ անցում չունեցող ճանապարհ։","Երթեւեկության ուղղությունը դեպի օբյեկտ, որը գտնվում է բնակավայրում։","Թափառքի գոտու կամ վերելքի վրա լրացուցիչ գոտու վերջը։"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":41,"page":21,"q":"Ո՞ր տրանսպորտային միջոցների երթեւեկությունն է թույլատրվում այս նշանի ազդեցության գոտում։","options":["Մեխանիկական տրանսպորտային միջոցների","Բոլոր տրանսպորտային միջոցների","Ավտոմոբիլների եւ մոտոցիկլների","Այն տրանսպորտային միջոցների, որոնց առավելագույն արագությունը գերազանցում է 40 կմ/ժ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":42,"page":21,"q":"Այս ճանապարհային նշաններից ո՞րը չի համարվում արգելող։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":43,"page":22,"q":"Ի՞նչ է նշանակում այս ճանաչման նշանը։","options":["Առջեւում երթեւեկելի մասի անհարթություններ ունեցող ճանապարհի հատված է","Առջեւում տվյալ ուղղությամբ երթեւեկելու համար երեք գոտի ունեցող ճանապարհի հատված է","Մեխանիկական տրանսպորտային միջոցի վրա տեղադրված են բութակավոր դողեր"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":44,"page":22,"q":"Նշաններից ո՞րն է կոչվում «Միակողմ երթեւեկությամբ ճանապարհի վերջ»։","options":["1","2","3","4","5"],"ans":4,"images_inline":["data:image/jpeg;base64,"]},{"n":45,"page":23,"q":"Նշաններից ո՞րն է պարտադրում զիջել ճանապարհը հատվող ճանապարհով ընթացող տրանսպորտային միջոցներին։","options":["1","2","3","4","5"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":46,"page":23,"q":"Հետեւյալ նշանները ցույց են տալիս","options":["Կայանման տեղը 30 մետրից` «Հաշմանդամներ» ճանաչման նշանով կահավորված ավտոմոբիլների համար։","Կայանման տեղը 30մ երկարությամբ գոտում` տրանսպորտային միջոցների համար` բացառությամբ մոտոսայլակների։","Կայանման տեղը 30մ երկարությամբ գոտում` մոտոսայլակների եւ «Հաշմանդամ» ճանաչման նշանով կահավորված ավտոմոբիլների համար։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":47,"page":24,"q":"Այս նշաններից ո՞րն է համարվում տրանսպորտային միջոցի ճանաչման նշան։","options":["1","2","3"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":48,"page":24,"q":"Ո՞ր տրանսպորտային միջոցի երթեւեկությունն է արգելում այս ճանապարհային նշանը։","options":["Մեխանիկական տրանսպորտային միջոցների","Միայն ավտոմոբիլների","Միայն թեթեւ մարդատար ավտոմոբիլների"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":49,"page":25,"q":"Նշաններից ո՞րն է ցույց տալիս արգելքի շրջանցումն աջից կամ ձախից։","options":["1","2","3","4","5"],"ans":5,"images_inline":["data:image/jpeg;base64,"]},{"n":50,"page":25,"q":"Նշաններից ո՞րն է տեղադրվում տրանսպորտային միջոցների առջեւի եւ ետեւի կողմերում` երեխաների կազմակերպված խմբեր տեղափոխելիս։","options":["1","2","3","4"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":51,"page":26,"q":"Ի՞նչ են ցույց տալիս նշված ճանապարհային նշանները։","options":["Գլխավոր ճանապարհը շարունակվում է խաչմերուկից դեպի ձախ","Գլխավոր ճանապարհը շարունակվում է խաչմերուկից ուղիղ եւ դեպի ձախ"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":52,"page":26,"q":"Ի՞նչ են ցույց տալիս նշված ճանապարհային նշանները։","options":["Ցուցանակի ազդեցության գոտում վարորդները պետք է երթեւեկեն նշանի վրա ցույց տրվածից ավելի բարձր արագությամբ","Ցուցանակի ազդեցության գոտում վարորդներին առաջարկվում է երթեւեկել նշանի վրա ցույց տրված արագությամբ"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":53,"page":27,"q":"Ո՞ր նշանների ազդեցությունն է գործում միայն այն ժամանակահատվածում, որի ընթացքում երթեւեկելի մասի ծածկույթը խոնավ է։","options":["Միայն A եւ C","Միայն B","Միայն C","Բոլոր"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":54,"page":27,"q":"Ինչպե՞ս պետք է վարվի վարորդը տվյալ իրադրությունում։","options":["Շարունակի երթևեկել ուղիղ","Վերադասավորվի ճանապարհի հանդիպակաց երթեւեկելի մաս"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":55,"page":28,"q":"Ի՞նչ են ցույց տալիս հետևյալ ճանապարհային նշանները։","options":["Նշանից 150-300մ հետո աջ կողմից կա ճանապարհի նեղացում, որի երկարությունը 100մ է","Նշանից 100մ հետո առկա է ճանապարհի նեղացում՝ աջ կողմից"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":56,"page":28,"q":"Ո՞ր ուղղությամբ է թույլատրվում վարորդին երթեւեկել։","options":["Միայն աջ եւ ձախ","Միայն ուղիղ","Ուղիղ եւ հակառակ ուղղությամբ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":57,"page":29,"q":"Ի՞նչ են ցույց տալիս նշված ճանապարհային նշանները։","options":["Կանգառն արգելված է շաբաթ օրերին","Կանգառն արգելված է կիրակի օրերին","Կանգառն արգելված է շաբաթ-կիրակի եւ տոն օրերին","Կանգառն արգելված է ձյունաթափի ժամանակ"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":58,"page":29,"q":"Ո՞ր ճանապարհային նշանն է արգելում հետադարձը։","options":["1","2","3"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":59,"page":30,"q":"Ի՞նչ են ցույց տալիս տվյալ ճանապարհային նշանները։","options":["Նորոգման աշխատանքների պատճառով կողնակ մուտք գործելը վտանգավոր է","Ճանապարհին իրականացվում են վերանորոգման աշխատանքներ"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":60,"page":30,"q":"Ի՞նչպես պիտի վարվի վարորդն այն դեպքում, երբ խաչմերուկից առաջ տեղադրված է հետեւյալ ճանապարհային նշանը։","options":["Անցնել խաչմերուկը` անվտանգությունը պահպանելով","Ճանապարհը զիջել հատվող ճանապարհով ընթացող տրանսպորտային միջոցներին","Կանգնել նշանի առջեւ եւ ճանապարհը զիջել հատվող ճանապարհով ընթացող տրանսպորտային միջոցներին"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":61,"page":31,"q":"Ո՞ր ճանապարհային նշանների ազդեցությունը չի տարածվում ընդհանուր օգտագործման տրանսպորտային միջոցների վրա։","options":["Ոչ մեկը","Միայն առաջինը","Միայն չորրորդը"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":62,"page":31,"q":"Հետեւյալ ճանապարհային նշանը ցույց է տալիս","options":["Խաչմերուկում պետք է երթեւեկել դեպի ձախ կամ աջ։","Հատվող ճանապարհին կազմակերպված է դարձափոխային երթեւեկություն։","Հատվող ճանապարհին կազմակերպված է միակողմանի երթեւեկություն։"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":63,"page":32,"q":"Տվյալ իրադրությունում պարտավո՞ր է վարորդը ճանապարհը զիջել բեռնատար ավտոմոբիլին։","options":["Պարտավոր է","Պարտավոր չէ"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":64,"page":32,"q":"Ի՞նչ են ցույց տալիս հետեւյալ ճանապարհային նշանները։","options":["Ճանապարհի սառցապատման ժամանակ պետք է երթեւեկել 40կմ/ժ արագությամբ","Թաց ճանապարհածածկույթի դեպքում պետք է երթեւեկել 40կմ/ժ-ից ոչ ավել արագությամբ"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":65,"page":33,"q":"Ի՞նչ են ցույց տալիս հետեւյալ ճանապարհային նշանները։","options":["Կանգառն արգելված է շաբաթ օրերին","Կանգառն արգելված է կիրակի օրերին","Կանգառն արգելված է աշխատանքային օրերին"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":66,"page":33,"q":"Ի՞նչ են ցույց տալիս հետեւյալ ճանապարհային նշանները։","options":["Ճանապարհի տվյալ հատվածում թույլատրվում է երթեւեկել ոչ ավել, քան 50 կմ/ժ արագությամբ","Առաջարկվում է ճանապարհի տվյալ հատվածում երթեւեկել 50 կմ/ժ արագությամբ","Թույլատրվում է երթևեկել միայն նշանում նշված կամ ավելի բարձր արագությամբ"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":67,"page":34,"q":"Ո՞ր ճանապարհային նշանն է պարտադրում վարորդին երթեւեկել միայն դեպի ձախ կամ դեպի աջ։","options":["1","2","3"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":68,"page":34,"q":"Ի՞նչ են ցույց տալիս հետեւյալ ճանապարհային նշանները։","options":["Թաց ճանապարհածածկույթի դեպքում առաջարկվում է երթեւեկել 40 կմ/ժ արագությամբ","Թաց ճանապարհածածկույթի դեպքում թույլատրվում է երթեւեկել ոչ ավել, քան 40 կմ/ժ արագությամբ"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":69,"page":35,"q":"Տվյալ ճանապարհային նշանների ազդեցությունը տարածվում է","options":["Ճանապարհի ձախ կողմում։","Ճանապարհի աջ կողմում։","Ճանապարհի այն կողմում, որտեղ դրանք տեղադրված են։"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":70,"page":35,"q":"Տվյալ իրադրությունում ո՞ր հետագծով է թույլատրվում արգելքի շրջանցումը։","options":["Միայն «A»","Միայն «B»","«A» եւ «B»"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":71,"page":36,"q":"Ինչպե՞ս պետք է վարվի վարորդը տվյալ իրավիճակում։","options":["Անհրաժեշտ է կանգ առնել առաջին նշանի մոտ","Անհրաժեշտ է կանգ առնել երկրորդ նշանից առաջ","Անհրաժեշտ է կանգ առնել երկաթուղային առաջին գծից ոչ պակաս, քան 5 մետր հեռավորության վրա"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":72,"page":36,"q":"Ի՞նչպես պետք է վարվի վարորդը, եթե խաչմերուկում մտադիր է կատարել աջ շրջադարձ։","options":["Կարող է վերադասավորվել աջ երթեւեկելի գոտի, դրանից հետո կատարել աջ շրջադարձ","Կարող է մոտենալ խաչմերուկին, այնուհետեւ կատարել աջ շրջադարձ","Երկու պատասխաններն էլ ճիշտ են"],"ans":3,"images_inline":["data:image/jpeg;base64,"]},{"n":73,"page":37,"q":"Տվյալ իրադրությունում նշանից 200 մ հեռավորության վրա վարորդն ունի՞ արդյոք հետադարձի իրավունք։","options":["Իրավունք ունի","Իրավունք չունի"],"ans":1,"images_inline":["data:image/jpeg;base64,"]},{"n":74,"page":37,"q":"Տվյալ դեպքում պարտավո՞ր է վարորդը կանգ առնել կարգավորողի կողմից նշված տեղում։","options":["Պարտավոր չէ, քանի որ նշանն արգելում է կանգառը","Պարտավոր է"],"ans":2,"images_inline":["data:image/jpeg;base64,"]},{"n":75,"page":38,"q":"Ինչպե՞ս պետք է վարվի վարորդը տվյալ իրավիճակում։","options":["Անցնի երկաթուղային գծանցը` ապահովելով անվտանգությունը","Անցնի երկաթուղային գծանցը՝ առանց կանգ առնելու","Կանգ առնի նշանից առաջ եւ, պահպանելով անվտանգությունը, անցնի բազմագիծ երկաթուղային գծանցը"],"ans":3,"images_inline":["data:image/jpeg;base64,"]}]);